def render_banner(hw_info: Optional[HardwareInfo] = None) -> str:
    """Builds and returns the complete side-by-side FlexSDS banner."""
    if hw_info is None:
        hw_info = detect_hardware()

    gpu_str = hw_info.summary()
    status_icon = "\033[32m✔\033[0m" if hw_info.is_cuda_available else "\033[33m!\033[0m"

    info_lines = [
        "",
        "\033[1;31m  ███████╗██╗     ███████╗██╗  ██╗███████╗██████╗ ███████╗\033[0m",
        "\033[1;31m  ██╔════╝██║     ██╔════╝╚██╗██╔╝██╔════╝██╔══██╗██╔════╝\033[0m",
        "\033[1;31m  █████╗  ██║     █████╗   ╚███╔╝ ███████╗██║  ██║███████╗\033[0m",
        "\033[1;31m  ██╔══╝  ██║     ██╔══╝   ██╔██╗ ╚════██║██║  ██║╚════██║\033[0m",
        "\033[1;31m  ██║     ███████╗███████╗██╔╝ ██╗███████║██████╔╝███████║\033[0m",
        "  \033[1;37mFlexSDS: Flexible Speculative Decoding Serving Engine · v0.2.0-alpha\033[0m",
        "  \033[90mPowered by TreeAdaptive & Hardware-Aware Profiling\033[0m",
        "  \033[33mHọc viện Công nghệ Bưu chính Viễn thông (PTIT)\033[0m",
        "",
        f"  {status_icon} Hardware : \033[1m{gpu_str}\033[0m",
        f"  \033[32m✔\033[0m Speculative: \033[1mTreeAdaptive (Hardware-Aware Dynamic k*)\033[0m",
        f"  \033[32m✔\033[0m Backends   : \033[1mModal Cloud (Serverless) / Local vLLM 0.30.0\033[0m",
    ]

    max_rows = max(len(PTIT_LOGO_ANSI), len(info_lines))
    col_logo = list(PTIT_LOGO_ANSI) + [" " * 26] * (max_rows - len(PTIT_LOGO_ANSI))
    col_info = list(info_lines) + [""] * (max_rows - len(info_lines))

    output = []
    for l, r in zip(col_logo, col_info):
        output.append(f" {l}  {r}")
    return "\n".join(output)


def print_banner(hw_info: Optional[HardwareInfo] = None) -> None:
    """Prints the banner directly to stdout."""
    print(render_banner(hw_info))


if __name__ == "__main__":
    print_banner()
